parameters.jsCode:
const intent = $input.item.json.choices[0].message.content.trim().toUpperCase();
const validIntents = ['UNDERSTAND', 'COMPARE', 'BREAKDOWN', 'QUERY', 'OTHER'];
const finalIntent = validIntents.includes(intent) ? intent : 'OTHER';

const intentPrompts = {
  UNDERSTAND: 'The user wants to understand WHY something changed or what drives a metric. Explain the drivers in plain everyday language. Identify the key factors and quantify their contribution where possible.',
  COMPARE: 'The user wants to COMPARE two or more things. Generate both a comparison in text and structured data for a comparison table. Identify which differences are statistically meaningful vs noise.',
  BREAKDOWN: 'The user wants to BREAKDOWN or decompose a number. Show the components that add up to the total. Provide both a narrative explanation and structured data for visualization.',
  QUERY: 'The user wants specific data. Generate a DuckDB SELECT query to retrieve exactly what they need, then present the results clearly.',
  OTHER: 'Answer helpfully based on the available schema and data context.'
};

return [{
  json: {
    intent: finalIntent,
    intent_prompt: intentPrompts[finalIntent]
  }
}];

// Build full message history for Groq
const history = $('Supabase: Fetch History').all();
const schema = $('MCP: get_schema_overview').item.json;
const intentData = $('Code: Route Intent').item.json;
const userMessage = $('Webhook: /chat').item.json.body.user_message;
const sessionId = $('Webhook: /chat').item.json.body.session_id;

// Reverse so oldest first
const historyMessages = history
  .map(item => item.json)
  .reverse()
  .map(msg => ({ role: msg.role, content: msg.content }));

const systemPrompt = `You are an expert data analyst assistant with access to the following database schema:
${JSON.stringify(schema, null, 2)}

Intent detected: ${intentData.intent}
${intentData.intent_prompt}

Rules:
- Always cite which table(s) and column(s) your answer draws from
- When generating chart data, return it in the JSON response under 'chart_data'
- If you need to query data, include a SELECT statement under 'query_to_run'
- Be concise. Skip preamble. Lead with the insight.
- Return a JSON object with: { "response_text": string, "chart_data": [] | null, "query_to_run": string | null, "sources": [string] }`;

return [{
  json: {
    session_id: sessionId,
    user_message: userMessage,
    intent: intentData.intent,
    messages_for_groq: [
      { role: 'system', content: systemPrompt },
      ...historyMessages,
      { role: 'user', content: userMessage }
    ]
  }
}];

const raw = $input.item.json.choices[0].message.content.trim();
const sessionId = $('Code: Build Full Prompt').item.json.session_id;
const userMessage = $('Code: Build Full Prompt').item.json.user_message;
const intent = $('Code: Build Full Prompt').item.json.intent;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  // If Groq didn't return JSON, treat as plain text response
  parsed = {
    response_text: raw,
    chart_data: null,
    query_to_run: null,
    sources: []
  };
}

return [{
  json: {
    session_id: sessionId,
    user_message: userMessage,
    assistant_response: parsed.response_text,
    chart_data: parsed.chart_data || null,
    sources: parsed.sources || [],
    intent: intent,
    query_to_run: parsed.query_to_run || null
  }
}];
